use std::fs

struct Tree {
    key: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut n: int = self.root
        while n >= 0 {
            let k: int = self.key[n]
            if x == k { return true }
            if x < k { n = self.l[n] } else { n = self.r[n] }
        }
        false
    }

    fn insert(self, x: int) {
        let id: int = self.key.len() as int
        self.key.push(x)
        self.l.push(-1)
        self.r.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n: int = self.root
        loop {
            if x < self.key[n] {
                if self.l[n] < 0 {
                    self.l[n] = id
                    return
                }
                n = self.l[n]
            } else {
                if self.r[n] < 0 {
                    self.r[n] = id
                    return
                }
                n = self.r[n]
            }
        }
    }

    fn min_of(self, start: int) -> int {
        let mut n: int = start
        while self.l[n] >= 0 { n = self.l[n] }
        self.key[n]
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 { return n }
        let k: int = self.key[n]
        if x < k {
            let c: int = self.del(self.l[n], x)
            self.l[n] = c
            return n
        }
        if x > k {
            let c: int = self.del(self.r[n], x)
            self.r[n] = c
            return n
        }
        let lc: int = self.l[n]
        let rc: int = self.r[n]
        if lc < 0 { return rc }
        if rc < 0 { return lc }
        let s: int = self.min_of(rc)
        self.key[n] = s
        let c: int = self.del(rc, s)
        self.r[n] = c
        n
    }

    fn height_of(self, n: int) -> int {
        if n < 0 { return 0 }
        let a: int = self.height_of(self.l[n])
        let b: int = self.height_of(self.r[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<string>) {
        if n < 0 { return }
        self.walk(self.l[n], out)
        out.push("${self.key[n]}")
        self.walk(self.r[n], out)
    }
}

fn main() {
    let mut t = Tree { key: [], l: [], r: [], root: -1 }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").map(|s| s.to_string()).collect()
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.contains(arg) { println("dup") } else {
                t.insert(arg)
                println("ok")
            }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.contains(arg) {
                let nr: int = t.del(t.root, arg)
                t.root = nr
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            t.walk(t.root, out)
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else { println("${t.min_of(t.root)}") }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut n: int = t.root
                while t.r[n] >= 0 { n = t.r[n] }
                println("${t.key[n]}")
            }
        }
    }
}

